head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[selectbox > E > onviewchange]<br/>컴포넌트에서 아이템의 선택이 사용자에 의해 키보드 또는 마우스로 변경되면 발생합니다.",
    "validation" : [        
        "컴포넌트에서 아이템의 선택이 사용자에 의해 키보드 또는 마우스로 변경되면 발생합니다.",
        "info 파라미터로 변경된 아이템에 대한 정보가 객체로 전달됩니다.",
        "info.oldValue 속성값으로 기존에 선택되어 있던 아이템의 Value 값을 갖습니다.",
        "info.oldValue 속성값으로 기존에 선택된 아이템이 없는 경우 ''(Empty String)값을 갖습니다.",
        "info.newValue 속성값으로 기존에 선택되어 있던 아이템의 Value 값을 갖습니다.",
        "info.oldSelectedIndex 속성값으로 새로 선택된 아이템의 인덱스값을 갖습니다",
        "info.oldSelectedIndex 속성값으로 기존에 선택된 아이템이 없는 경우 -1 값을 갖습니다.",        
        "info.newSelectedIndex 속성값으로 새로 선택된 아이템의 인덱스값을 갖습니다.",
        "기존과 동일한 아이템을 선택한 경우 onviewchange 이벤트는 발생하지 않습니다.",
        "스크립트에서 setValue(), setSelectedIndex() 메소드로 아이템의 선택을 변경한 경우 onviewchange 이벤트는 발생하지 않습니다."
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정    
    let properties = {
        emptyItem: true,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onviewchange"])

    // comp 생성 함수 호출    
    $c.gcm.createBasicSelectBox(cList, eList); 
}



scwin.btn_setSelectedIndex_onclick = function (e) {
	target1.setSelectedIndex(par_index.getText());
};



scwin.btn_setValue_onclick = function (e) {
    let value = par_value.getText();

    if (value == '')
	    target1.setValue();
    else
        target1.setValue(value);
};




scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldSelectedIndex : " + info.oldSelectedIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newSelectedIndex : " + info.newSelectedIndex);
}
